<script lang="ts">
 import RichTextEditor from '../modules/routingtales/shared/RichTextEditor.svelte';
 import {interfaceLanguage} from './context.svelte';import {languageName} from './locale';import {adventureLanguages} from './adventure';import {translationFields,translationStatus,translationValue,translationCoverage,writeTranslation,type TranslationCategory,type TranslationField} from './translation-catalogue';import type {Adventure} from '../demo/adventure';import {Search,Languages,Check,AlertTriangle,FileText} from 'lucide-svelte';
 const ui=interfaceLanguage();let {adventure,onchange}:{adventure:Adventure;onchange:(adventure:Adventure,checkpoint:boolean)=>void}=$props();
 let target=$state(''),search=$state(''),filter=$state<'all'|'missing'|'outdated'>('all'),category=$state<TranslationCategory|'all'>('all'),error=$state(''),editingKey=$state(''),expanded=$state<Record<string,boolean>>({});
 const languages=$derived(adventureLanguages(adventure).filter(locale=>locale!==(adventure.localization?.defaultLocale??'es')));
 const locale=$derived(languages.includes(target)?target:languages[0]??'');
 const fields=$derived(translationFields(adventure)),coverage=$derived(translationCoverage(adventure,locale,fields));
 const filtered=$derived(fields.filter(field=>(category==='all'||category===field.category)&&(filter==='all'||translationStatus(adventure,locale,field)===filter)&&`${field.context} ${field.source} ${translationValue(adventure,locale,field)}`.toLocaleLowerCase().includes(search.toLocaleLowerCase())));
 const groups:Record<TranslationCategory,string>={adventure:'Aventura',maps:'Mapas',objects:'Objetos',items:'Inventario',events:'Eventos',modules:'Módulos',chats:'Conversaciones'};
 function update(field:TranslationField,value:string){try{onchange(writeTranslation(adventure,locale,field.key,value),editingKey!==locale+field.key);editingKey=locale+field.key;error='';}catch(e){error=(e as Error).message;}}
</script>
<section class="translations" aria-label={ui.text('Traducciones de la aventura')}><h3><Languages size={17}/>{ui.text('Traducciones')}</h3>
{#if !languages.length}<p>{ui.text('Activa otro idioma para empezar a traducir esta aventura.')}</p>{:else}
 <div class="filters"><label>{ui.text('Idioma de destino')}<select aria-label={ui.text('Idioma de destino')} value={locale} onchange={e=>target=e.currentTarget.value}>{#each languages as language}<option value={language}>{languageName(language)}</option>{/each}</select></label><label>{ui.text('Sección')}<select aria-label={ui.text('Sección de traducciones')} bind:value={category}><option value="all">{ui.text('Todas')}</option>{#each Object.entries(groups) as [id,label]}<option value={id}>{ui.text(label)}</option>{/each}</select></label><label>{ui.text('Estado')}<select aria-label={ui.text('Estado de traducción')} bind:value={filter}><option value="all">{ui.text('Todos')}</option><option value="missing">{ui.text('Pendientes')}</option><option value="outdated">{ui.text('Desactualizadas')}</option></select></label></div>
 <div class="coverage" role="status"><strong>{coverage.translated}/{coverage.total}</strong><span>{ui.text('Traducidos')} · {coverage.missing} {ui.text('Pendientes')} · {coverage.outdated} {ui.text('Desactualizadas')}</span></div><progress aria-label={ui.text('Cobertura de traducción')} max={Math.max(1,coverage.total)} value={coverage.translated}></progress>
 <label class="search"><Search size={14}/><input aria-label={ui.text('Buscar textos')} placeholder={ui.text('Buscar textos…')} bind:value={search}/></label>
 <p class="hint">{ui.text('Guardar la aventura conserva las traducciones. Publicar actualiza la versión pública.')}</p>
 {#if error}<p class="error" role="alert">{ui.text(error)}</p>{/if}
 <div class="text-list">{#each filtered as field(field.key)}{@const status=translationStatus(adventure,locale,field)}<details class:outdated={status==='outdated'} ontoggle={event=>expanded={...expanded,[field.key]:event.currentTarget.open}} onfocusout={event=>{if(!(event.relatedTarget instanceof Node)||!event.currentTarget.contains(event.relatedTarget))editingKey='';}}><summary><span>{#if status==='translated'}<Check size={14}/>{:else if status==='outdated'}<AlertTriangle size={14}/>{:else}<FileText size={14}/>{/if}{ui.text(field.label)}<small>{field.context}</small></span><small class="status">{ui.text(status==='translated'?'Traducido':status==='outdated'?'Desactualizado':'Pendiente')}</small></summary>{#if expanded[field.key]}<label>{ui.text('Original')}{#if field.kind==='rich'}<RichTextEditor interfaceLocale={ui.locale} readOnly label={ui.text('Texto original')+' · '+field.context+' · '+ui.text(field.label)} value={field.source}/>{:else}<textarea readonly aria-label={ui.text('Texto original')+' · '+field.context+' · '+ui.text(field.label)} value={field.source} rows="3"></textarea>{/if}</label><label>{languageName(locale)}{#if field.kind==='rich'}<RichTextEditor interfaceLocale={ui.locale} label={ui.text('Traducción')+' · '+field.context+' · '+ui.text(field.label)} value={translationValue(adventure,locale,field)} toolbarMode="enhanced" on:change={event=>update(field,event.detail)}/>{:else}<textarea aria-label={ui.text('Traducción')+' · '+field.context+' · '+ui.text(field.label)} value={translationValue(adventure,locale,field)} oninput={e=>update(field,e.currentTarget.value)} rows="3"></textarea>{/if}</label>{#if field.kind==='rich'}<small>{ui.text('El editor conserva el formato del contenido.')}</small>{/if}{#if status==='outdated'}<p class="hint">{ui.text('El original ha cambiado. Revisa la traducción antes de validarla.')}</p><button onclick={()=>update(field,translationValue(adventure,locale,field))}>{ui.text('Validar traducción revisada')}</button>{/if}{/if}</details>{:else}<p>{ui.text('No hay textos con este filtro.')}</p>{/each}</div>
{/if}</section>
<style>.translations{font-size:12px}.translations h3{display:flex;align-items:center;gap:7px;font-size:14px;margin:20px 0 12px}.filters{display:grid;grid-template-columns:1fr 1fr;gap:8px}.filters label:last-child{grid-column:1/-1}label{display:block;font-size:11px;color:#607168;margin:8px 0}select,input,textarea{box-sizing:border-box;width:100%;border:1px solid #d5dfce;border-radius:6px;background:white;color:#35502f;padding:8px;font:12px system-ui;margin-top:5px}textarea{resize:vertical;line-height:1.5;min-height:76px}textarea[readonly]{background:#f0f4ec}.coverage{display:flex;gap:8px;align-items:center;margin-top:14px;font-size:11px}progress{width:100%;height:7px;accent-color:#577c35}.search{position:relative}.search :global(svg){position:absolute;left:8px;top:13px}.search input{padding-left:29px}.hint{font-size:11px;line-height:1.5;color:#74816e}.text-list{display:flex;flex-direction:column;gap:8px}.text-list details{border:1px solid #dce4d6;border-radius:8px;padding:10px}.text-list details.outdated{border-color:#d8ba7c}summary{display:flex;align-items:center;justify-content:space-between;gap:8px;cursor:pointer}summary>span{min-width:0;flex:1}summary :global(svg){display:inline-block;vertical-align:middle;margin-right:4px}summary small:not(.status){display:block;overflow-wrap:anywhere;font-size:10px;color:#74816e;margin:4px 0}.status{font-size:9px;flex:none;color:#74816e}button{padding:7px 9px;font:11px system-ui;border:1px solid #d5dfce;border-radius:6px;background:#edf3e5;color:#35502f;cursor:pointer}.error{color:#993d2f}select:focus-visible,input:focus-visible,textarea:focus-visible,button:focus-visible,summary:focus-visible{outline:2px solid #789557;outline-offset:2px}</style>
